# ── Phenotype catalogue ───────────────────────────────────────────────────────
# One bash function serves both dispatch paths below: SLURM calls it once per array
# task (with the task id it sets), the local profile calls it in a loop over every row.
# Each case sets the TRAIT and its per-row options, then hands them to the single runner.
dispatch_phenotype() {
    local task_id="$1"
    case "$task_id" in
    1) TRAIT="marine"; SECONDARY="control"; NTRAIT=""; CTRAIT=""; PRUNE=""; PRUNE_SEC="marine_tips.txt"; TRAIT_TYPE="ordinal"
        ;;
    2) TRAIT="control"; SECONDARY="marine"; NTRAIT=""; CTRAIT=""; PRUNE="marine_tips.txt"; PRUNE_SEC=""; TRAIT_TYPE="ordinal"
        ;;
    *)
        echo "Error: no phenotype row configured for task id '$task_id'" >&2
        return 1
        ;;
    esac

    echo "======================================================"
    echo " TASK ID       : $task_id"
    echo " TRAIT         : $TRAIT"
    echo "======================================================"

    bash "$SINGLE_RUNNER" "$TRAIT" "$SECONDARY" "$NTRAIT" "$CTRAIT" "$PRUNE" "$PRUNE_SEC" "$TRAIT_TYPE"
}

# Local profile: no scheduler fans the tasks out, so this process runs every
# phenotype row sequentially.
for task_id in $(seq 1 2); do
    dispatch_phenotype "$task_id"
done
